    try { apply(render(content, { ...mermaidOptions, idPrefix }).svg); }
    catch { apply('<p role="status">Diagram unavailable. Check its source.</p>'); }
  }).catch(() => apply('<p role="status">Diagram unavailable. Check its source.</p>'));
}
